CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE tenants(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL);
CREATE TABLE units(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),name text NOT NULL, UNIQUE(tenant_id,id));
CREATE TABLE users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,email text UNIQUE NOT NULL);
CREATE TABLE memberships(tenant_id uuid REFERENCES tenants(id),user_id uuid REFERENCES users(id),role text NOT NULL CHECK(role IN('ADMIN','MANAGEMENT','RECEPTION','CLINICIAN','AUDIT','FINANCE')),unit_ids uuid[] NOT NULL DEFAULT '{}',active boolean NOT NULL DEFAULT true, PRIMARY KEY(tenant_id,user_id));
CREATE TABLE sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),user_id uuid NOT NULL REFERENCES users(id),refresh_hash text NOT NULL,csrf_hash text NOT NULL,expires_at timestamptz NOT NULL,revoked_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE rate_limits(key text PRIMARY KEY,count int NOT NULL,expires_at timestamptz NOT NULL);
CREATE TABLE insurers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),name text NOT NULL,rules jsonb NOT NULL DEFAULT '{}',version int NOT NULL DEFAULT 1, UNIQUE(tenant_id,id));
CREATE TABLE rooms(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),unit_id uuid NOT NULL,name text NOT NULL,capacity int NOT NULL CHECK(capacity BETWEEN 1 AND 10),FOREIGN KEY(tenant_id,unit_id) REFERENCES units(tenant_id,id),UNIQUE(tenant_id,id));
CREATE TABLE professionals(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),unit_id uuid NOT NULL,room_id uuid NOT NULL,name text NOT NULL,specialty text NOT NULL,contract text NOT NULL CHECK(contract IN('PJ','CLT')),active boolean NOT NULL DEFAULT true,competencies text[] NOT NULL DEFAULT '{}',hourly_rate numeric(12,2) NOT NULL DEFAULT 0,metadata jsonb NOT NULL DEFAULT '{}',version int NOT NULL DEFAULT 1,FOREIGN KEY(tenant_id,unit_id) REFERENCES units(tenant_id,id),FOREIGN KEY(tenant_id,room_id) REFERENCES rooms(tenant_id,id),UNIQUE(tenant_id,id));
CREATE TABLE patients(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),unit_id uuid NOT NULL,name text NOT NULL,birth_date date NOT NULL,guardian text NOT NULL,phone text NOT NULL,insurer_id uuid NOT NULL,card_number text NOT NULL DEFAULT '',metadata jsonb NOT NULL DEFAULT '{}',version int NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(tenant_id,unit_id) REFERENCES units(tenant_id,id),FOREIGN KEY(tenant_id,insurer_id) REFERENCES insurers(tenant_id,id),UNIQUE(tenant_id,id));
CREATE TABLE appointments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),unit_id uuid NOT NULL,patient_id uuid NOT NULL,professional_id uuid NOT NULL,room_id uuid NOT NULL,starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,status text NOT NULL DEFAULT 'SCHEDULED' CHECK(status IN('SCHEDULED','ARRIVED','IN_PROGRESS','COMPLETED','ABSENT','CANCELLED')),authorization_status text NOT NULL DEFAULT 'PENDING' CHECK(authorization_status IN('PENDING','MANUAL')),authorization_evidence text,signature_evidence text,arrival_by uuid REFERENCES users(id),arrived_at timestamptz,started_at timestamptz,evolution text,audit_status text NOT NULL DEFAULT 'PENDING' CHECK(audit_status IN('PENDING','APPROVED','RETURNED','REJECTED')),reason text,series_id uuid,version int NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),CHECK(ends_at>starts_at),FOREIGN KEY(tenant_id,unit_id) REFERENCES units(tenant_id,id),FOREIGN KEY(tenant_id,patient_id) REFERENCES patients(tenant_id,id),FOREIGN KEY(tenant_id,professional_id) REFERENCES professionals(tenant_id,id),FOREIGN KEY(tenant_id,room_id) REFERENCES rooms(tenant_id,id),UNIQUE(tenant_id,id));
CREATE INDEX appointments_schedule ON appointments(tenant_id,unit_id,starts_at);
CREATE INDEX appointments_prof ON appointments(tenant_id,professional_id,starts_at,ends_at) WHERE status NOT IN('CANCELLED','ABSENT');
CREATE TABLE clinical_entries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),patient_id uuid NOT NULL,professional_id uuid,kind text NOT NULL CHECK(kind IN('EVOLUTION','ANAMNESIS','ASSESSMENT','PLAN','REPORT')),content text NOT NULL,model_snapshot jsonb,created_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(tenant_id,patient_id) REFERENCES patients(tenant_id,id),FOREIGN KEY(tenant_id,professional_id) REFERENCES professionals(tenant_id,id));
CREATE TABLE documents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),unit_id uuid NOT NULL,patient_id uuid,name text NOT NULL,mime text NOT NULL CHECK(mime='application/pdf'),content bytea NOT NULL,created_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),CHECK(octet_length(content)<=2097152),FOREIGN KEY(tenant_id,unit_id) REFERENCES units(tenant_id,id),FOREIGN KEY(tenant_id,patient_id) REFERENCES patients(tenant_id,id),UNIQUE(tenant_id,id));
CREATE TABLE ledger(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),unit_id uuid NOT NULL,description text NOT NULL,kind text NOT NULL CHECK(kind IN('INCOME','EXPENSE')),amount numeric(12,2) NOT NULL CHECK(amount>0),due_date date NOT NULL,category text NOT NULL,counterparty text NOT NULL DEFAULT '',status text NOT NULL DEFAULT 'OPEN' CHECK(status IN('OPEN','SETTLED')),appointment_id uuid,version int NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(tenant_id,unit_id) REFERENCES units(tenant_id,id),FOREIGN KEY(tenant_id,appointment_id) REFERENCES appointments(tenant_id,id),UNIQUE(tenant_id,id));
CREATE TABLE payment_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),ledger_id uuid NOT NULL,kind text NOT NULL CHECK(kind IN('SETTLEMENT','REVERSAL')),paid_date date,method text,counterparty text,reference text,notes text,document_id uuid,created_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(tenant_id,ledger_id) REFERENCES ledger(tenant_id,id),FOREIGN KEY(tenant_id,document_id) REFERENCES documents(tenant_id,id));
CREATE TABLE inventory(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),unit_id uuid NOT NULL,name text NOT NULL,quantity int NOT NULL CHECK(quantity>=0),minimum int NOT NULL CHECK(minimum>=0),version int NOT NULL DEFAULT 1,FOREIGN KEY(tenant_id,unit_id) REFERENCES units(tenant_id,id),UNIQUE(tenant_id,id));
CREATE TABLE inventory_movements(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),item_id uuid NOT NULL,delta int NOT NULL CHECK(delta<>0),reason text NOT NULL,created_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(tenant_id,item_id) REFERENCES inventory(tenant_id,id));
CREATE TABLE agents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),name text NOT NULL,specialty text NOT NULL,instructions text NOT NULL,knowledge text NOT NULL,enabled boolean NOT NULL DEFAULT true,confidence_threshold int NOT NULL DEFAULT 80 CHECK(confidence_threshold BETWEEN 60 AND 100),version int NOT NULL DEFAULT 1,UNIQUE(tenant_id,id));
CREATE TABLE agent_versions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),agent_id uuid NOT NULL,version int NOT NULL,snapshot jsonb NOT NULL,created_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(tenant_id,agent_id) REFERENCES agents(tenant_id,id));
CREATE TABLE assessment_models(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),name text NOT NULL,specialty text NOT NULL,questions jsonb NOT NULL,version int NOT NULL DEFAULT 1,UNIQUE(tenant_id,id));
CREATE TABLE conversations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),unit_id uuid NOT NULL,patient_id uuid,guardian text NOT NULL,channel text NOT NULL DEFAULT 'LOCAL',status text NOT NULL DEFAULT 'WAITING' CHECK(status IN('WAITING','HUMAN','REVIEW','DONE')),priority text NOT NULL DEFAULT 'NORMAL' CHECK(priority IN('NORMAL','HIGH')),assigned_to text,summary text NOT NULL DEFAULT '',version int NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(tenant_id,unit_id) REFERENCES units(tenant_id,id),FOREIGN KEY(tenant_id,patient_id) REFERENCES patients(tenant_id,id),UNIQUE(tenant_id,id));
CREATE TABLE messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),conversation_id uuid NOT NULL,direction text NOT NULL CHECK(direction IN('INBOUND','OUTBOUND','SYSTEM')),content text NOT NULL,created_by uuid REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(tenant_id,conversation_id) REFERENCES conversations(tenant_id,id));
CREATE TABLE audit_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),unit_id uuid,actor_id uuid NOT NULL REFERENCES users(id),action text NOT NULL,entity_type text NOT NULL,entity_id uuid,details jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX audit_tenant_time ON audit_events(tenant_id,created_at DESC);
CREATE FUNCTION immutable_history() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Histórico imutável'; END; $$;
CREATE TRIGGER protect_audit BEFORE UPDATE OR DELETE ON audit_events FOR EACH ROW EXECUTE FUNCTION immutable_history();
CREATE TRIGGER protect_payments BEFORE UPDATE OR DELETE ON payment_events FOR EACH ROW EXECUTE FUNCTION immutable_history();
CREATE TRIGGER protect_movements BEFORE UPDATE OR DELETE ON inventory_movements FOR EACH ROW EXECUTE FUNCTION immutable_history();
CREATE TRIGGER protect_clinical BEFORE UPDATE OR DELETE ON clinical_entries FOR EACH ROW EXECUTE FUNCTION immutable_history();
